  <gco:CharacterString>https://bio.discomap.eea.europa.eu/arcgis/rest/services/ProtectedSites/CDDAv20_Dyna_LAEA/MapServer</gco:CharacterString>\r\n              </cit:linkage>\r\n              <cit:protocol>\r\n                <gco:CharacterString>ESRI:REST</gco:CharacterString>\r\n              </cit:protocol>\r\n              <cit:description>\r\n                <gco:CharacterString>LAEA</gco:CharacterString>\r\n              </cit:description>\r\n            </cit:CI_OnlineResource>\r\n          </mrd:onLine>\r\n        </mrd:MD_DigitalTransferOptions>\r\n      </mrd:transferOptions>\r\n    </mrd:MD_Distribution>\r\n  </mdb:distributionInfo>\r\n  <mdb:dataQualityInfo>\r\n    <mdq:DQ_DataQuality>\r\n      <mdq:scope>\r\n        <mcc:MD_Scope>\r\n          <mcc:level>\r\n            <mcc:MD_ScopeCode codeListValue="dataset" codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#MD_ScopeCode" />\r\n          </mcc:level>\r\n        </mcc:MD_Scope>\r\n      </mdq:scope>\r\n      <mdq:report>\r\n        <mdq:DQ_DomainConsistency>\r\n          <mdq:result>\r\n            <mdq:DQ_ConformanceResult>\r\n              <mdq:specification>\r\n                <cit:CI_Citation>\r\n                  <cit:title>\r\n                    <gcx:Anchor xlink:href="">Commission Regulation (EU) No 1089/2010 of 23 November 2010 implementing Directive 2007/2/EC of the European Parliament and of the Council as regards interoperability of spatial data sets and services</gcx:Anchor>\r\n                  </cit:title>\r\n                  <cit:date>\r\n                    <cit:CI_Date>\r\n                      <cit:date>\r\n                        <gco:Date>2010-12-08</gco:Date>\r\n                      </cit:date>\r\n                      <cit:dateType>\r\n                        <cit:CI_DateTypeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_DateTypeCode" codeListValue="publication" />\r\n                      </cit:dateType>\r\n                    </cit:CI_Date>\r\n                  </cit:date>\r\n                </cit:CI_Citation>\r\n              </mdq:specification>\r\n              <mdq:explanation>\r\n                <gco:CharacterString>See the referenced specification</gco:CharacterString>\r\n              </mdq:explanation>\r\n              <mdq:pass gco:nilReason="unknown" />\r\n            </mdq:DQ_ConformanceResult>\r\n          </mdq:result>\r\n        </mdq:DQ_DomainConsistency>\r\n      </mdq:report>\r\n    </mdq:DQ_DataQuality>\r\n  </mdb:dataQualityInfo>\r\n  <mdb:resourceLineage>\r\n    <mrl:LI_Lineage>\r\n      <mrl:statement>\r\n        <gco:CharacterString>The data sources for this dataset are data deliveries from the Eionet, the partnership network of the EEA and its 38 member and cooperating countries. In EU Member States the implementation of INSPIRE Directive may mean that the spatial information is provided via the national or sub-national INSPIRE data providers.\r\n\r\nThe reference data used in the validation process is the EBM 2020, Jan. 2020 (https://sdi.eea.europa.eu/catalogue/srv/eng/catalog.search#/metadata/3275ecdb-a6c5-4ffe-875f-c0b2bfcc5786).\r\n\r\nThe dataset is accompanied with a series of files and documents for download: CDDA_2022_v01_public_DesignatedArea.csv, which includes information on the nationally designated sites and designated boundaries for public dissemination; CDDA_2022_v01_public_DesignationType.csv, which contains information about designation types and the national and international legislative instruments, which directly or indirectly create protected designated areas in Europe.</gco:CharacterString>\r\n      </mrl:statement>\r\n      <mrl:scope>\r\n        <mcc:MD_Scope>\r\n          <mcc:level>\r\n            <mcc:MD_ScopeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#MD_ScopeCode" codeListValue="dataset" />\r\n          </mcc:level>\r\n        </mcc:MD_Scope>\r\n      </mrl:scope>\r