 <cit:CI_Date>\r\n              <cit:date>\r\n                <gco:Date>2020-04-16</gco:Date>\r\n              </cit:date>\r\n              <cit:dateType>\r\n                <cit:CI_DateTypeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_DateTypeCode" codeListValue="creation" />\r\n              </cit:dateType>\r\n            </cit:CI_Date>\r\n          </cit:date>\r\n          <cit:date>\r\n            <cit:CI_Date>\r\n              <cit:date>\r\n                <gco:Date>2020-04-16</gco:Date>\r\n              </cit:date>\r\n              <cit:dateType>\r\n                <cit:CI_DateTypeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_DateTypeCode" codeListValue="publication" />\r\n              </cit:dateType>\r\n            </cit:CI_Date>\r\n          </cit:date>\r\n          <cit:date>\r\n            <cit:CI_Date>\r\n              <cit:date>\r\n                <gco:Date>2021-07-16</gco:Date>\r\n              </cit:date>\r\n              <cit:dateType>\r\n                <cit:CI_DateTypeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_DateTypeCode" codeListValue="revision" />\r\n              </cit:dateType>\r\n            </cit:CI_Date>\r\n          </cit:date>\r\n          <cit:edition>\r\n            <gco:CharacterString>01.03</gco:CharacterString>\r\n          </cit:edition>\r\n          <cit:identifier>\r\n            <mcc:MD_Identifier>\r\n              <mcc:code>\r\n                <gco:CharacterString>copernicus_v_3035_10_m_ua-2018_p_2017-2019_v01_r03</gco:CharacterString>\r\n              </mcc:code>\r\n            </mcc:MD_Identifier>\r\n          </cit:identifier>\r\n          <cit:identifier>\r\n            <mcc:MD_Identifier>\r\n              <mcc:code>\r\n                <gco:CharacterString>DAT-190-en</gco:CharacterString>\r\n              </mcc:code>\r\n            </mcc:MD_Identifier>\r\n          </cit:identifier>\r\n          <cit:identifier>\r\n            <mcc:MD_Identifier>\r\n              <mcc:code>\r\n                <gcx:Anchor xlink:href="https://doi.org/10.2909/fb4dffa1-6ceb-4cc0-8372-1ed354c285e6">10.2909/fb4dffa1-6ceb-4cc0-8372-1ed354c285e6</gcx:Anchor>\r\n              </mcc:code>\r\n            </mcc:MD_Identifier>\r\n          </cit:identifier>\r\n        </cit:CI_Citation>\r\n      </mri:citation>\r\n      <mri:abstract>\r\n        <gco:CharacterString>Urban Atlas 2018 provides reliable, inter-comparable, high-resolution land use and land cover data with integrated population estimates for 788 Functional Urban Areas (FUA) with more than 50,000 inhabitants for the 2018 reference year in EEA38 countries (EU, EFTA, Western Balkans countries, as well as Türkiye) and the United Kingdom. \r\n\r\nUrban Atlas is a joint initiative of the European Commission Directorate-General for Regional and Urban Policy and the Directorate-General for Defence Industry and Space in the frame of the EU Copernicus programme, with the support of the European Space Agency and the European Environment Agency.\r\n\r\nPer each of the FUAs, a ZIP is provided which includes: (1) the vector data in OGC GeoPackage SQLite format (ETRS89-LAEA, EPSG:3035); (2) PDF document with a high-resolution map of the area; (3) PDF document with the delivery report; (4) symbology files in .lyr, .qml and .sld formats; and (5) a xml document with metadata.</gco:CharacterString>\r\n      </mri:abstract>\r\n      <mri:pointOfContact>\r\n        <cit:CI_Responsibility>\r\n          <cit:role>\r\n            <cit:CI_RoleCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_RoleCode" codeListValue="owner" />\r\n          </cit:role>\r\n          <cit:party>\r\n            <cit:CI_Organisation>\r\n              <cit:name>\r\n                <gco:CharacterString>European Commission</gco:CharacterString>\r\n              </cit:name>\r\n              <cit:contactInfo>\r\n                <cit:CI_Contact>\r\n                  <cit:onlineResource>\r\n                    <cit:CI_OnlineResource>\r\n                      <cit:linkage>\r\n                        <gco:CharacterString>https://commission.europa.eu</gco:CharacterString>\r\n                      </cit:linkage>\r\n                    </cit:CI_OnlineResource>\r\n                  </cit:onlineResource>\r\n                </cit:CI_Contact>\r\n              </cit:contactInfo>\r\n            </cit:CI_Organisation>\r\n          </cit:party>\r\n        </cit:CI_Responsibility>\r\n      </mri:pointOfContact>\r\n      <mri:pointOfContact>\r\n        <cit:CI_Responsibility>\r\n          <cit:role>\r\n            <cit:CI_RoleCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_RoleCode" codeListValue="custodian" />\r\n          </cit:role>\r\n          <cit:party>\r\n            <cit:CI_Organisation>\r\n              <cit:name>\r\n                <gco:CharacterString>Copernicus Land Monitoring Service</gco:CharacterString>\r\n              </cit:name>\r\n              <cit:contactInfo>\r\n                <cit:CI_Contact>\r\n                  <cit:address>\r\n                    <cit:CI_Address>\r\n                      <cit:electronicMailAddress>\r\n                        <gco:CharacterString>JRC-Copernicus-Land@ec.europa.eu</gco:CharacterString>\r\n                      </cit:electronicMailAddress>\r\n                    </cit:CI_Address>\r\n                  </cit:address>\r\n                  <cit:onlineResource>\r\n                    <cit:CI_OnlineResource>\r\n                      <cit:linkage>\r\n                        <gco:CharacterString>https://land.copernicus.eu</gco:CharacterString>\r\n                      </cit:linkage>\r\n                    </cit:CI_OnlineResource>\r\n                  </cit:onlineResource>\r\n                </cit:CI_Contact>\r\n              </cit:contactInfo>\r\n            </cit:CI_Organisation>\r\n          </cit:party>\r\n     