\r\n  <mdb:dataQualityInfo>\r\n    <mdq:DQ_DataQuality>\r\n      <mdq:scope>\r\n        <mcc:MD_Scope>\r\n          <mcc:level>\r\n            <mcc:MD_ScopeCode codeListValue="dataset" codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#MD_ScopeCode" />\r\n          </mcc:level>\r\n        </mcc:MD_Scope>\r\n      </mdq:scope>\r\n      <mdq:report>\r\n        <mdq:DQ_DomainConsistency>\r\n          <mdq:result />\r\n        </mdq:DQ_DomainConsistency>\r\n      </mdq:report>\r\n      <mdq:report>\r\n        <mdq:DQ_DomainConsistency>\r\n          <mdq:result>\r\n            <mdq:DQ_ConformanceResult>\r\n              <mdq:specification>\r\n                <cit:CI_Citation>\r\n                  <cit:title>\r\n                    <gcx:Anchor xlink:href="">Commission Regulation (EU) No 1089/2010 of 23 November 2010 implementing Directive 2007/2/EC of the European Parliament and of the Council as regards interoperability of spatial data sets and services</gcx:Anchor>\r\n                  </cit:title>\r\n                  <cit:date>\r\n                    <cit:CI_Date>\r\n                      <cit:date>\r\n                        <gco:Date>2010-12-08</gco:Date>\r\n                      </cit:date>\r\n                      <cit:dateType>\r\n                        <cit:CI_DateTypeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_DateTypeCode" codeListValue="publication" />\r\n                      </cit:dateType>\r\n                    </cit:CI_Date>\r\n                  </cit:date>\r\n                </cit:CI_Citation>\r\n              </mdq:specification>\r\n              <mdq:explanation>\r\n                <gco:CharacterString>See the referenced specification</gco:CharacterString>\r\n              </mdq:explanation>\r\n              <mdq:pass gco:nilReason="unknown" />\r\n            </mdq:DQ_ConformanceResult>\r\n          </mdq:result>\r\n        </mdq:DQ_DomainConsistency>\r\n      </mdq:report>\r\n      <mdq:report>\r\n        <mdq:DQ_AbsoluteExternalPositionalAccuracy>\r\n          <mdq:measure>\r\n            <mdq:DQ_MeasureReference>\r\n              <mdq:nameOfMeasure>\r\n                <gco:CharacterString>Minimum Mapping Unit</gco:CharacterString>\r\n              </mdq:nameOfMeasure>\r\n            </mdq:DQ_MeasureReference>\r\n          </mdq:measure>\r\n          <mdq:result>\r\n            <mdq:DQ_QuantitativeResult>\r\n              <mdq:valueUnit>\r\n                <gml:UnitDefinition gml:id="d3888e669a1051934">\r\n                  <gml:identifier codeSpace="">ha</gml:identifier>\r\n                </gml:UnitDefinition>\r\n              </mdq:valueUnit>\r\n              <mdq:value>\r\n                <gco:Record>urban areas = 0.25</gco:Record>\r\n              </mdq:value>\r\n            </mdq:DQ_QuantitativeResult>\r\n          </mdq:result>\r\n        </mdq:DQ_AbsoluteExternalPositionalAccuracy>\r\n      </mdq:report>\r\n      <mdq:report>\r\n        <mdq:DQ_AbsoluteExternalPositionalAccuracy>\r\n          <mdq:measure>\r\n            <mdq:DQ_MeasureReference>\r\n              <mdq:nameOfMeasure>\r\n                <gco:CharacterString>Minimum Mapping Unit</gco:CharacterString>\r\n              </mdq:nameOfMeasure>\r\n            </mdq:DQ_MeasureReference>\r\n          </mdq:measure>\r\n          <mdq:result>\r\n            <mdq:DQ_QuantitativeResult>\r\n              <mdq:valueUnit>\r\n                <gml:UnitDefinition gml:id="d3888e669a10aa51934">\r\n                  <gml:identifier codeSpace="">ha</gml:identifier>\r\n                </gml:UnitDefinition>\r\n              </mdq:valueUnit>\r\n              <mdq:value>\r\n                <gco:Record>rural areas = 1</gco:Record>\r\n              </mdq:value>\r\n            </mdq:DQ_QuantitativeResult>\r\n          </mdq:result>\r\n        </mdq:DQ_AbsoluteExternalPositionalAccuracy>\r\n      </mdq:report>\r\n    </mdq:DQ_DataQuality>\r\n  </mdb:dataQualityInfo>\r\n  <mdb:resourceLineage>\r\n    <mrl:LI_Lineage>\r\n      <mrl:statement>\r\n        <gco:CharacterString>Cartography based on VHR satellite images interpretation: Pléiades, SuperView, KOMPSAT-2-3, PlanetScope, SPOT6-7, TripleSat, GeoSat-2 (resolution 2 or 4 meters) acquired within predefined windows corresponding to the vegetation season in 2017, 2018 and 2019.\r\n\r\nThe dataset maps land cover and land use in Functional Urban Areas (FUA) for 17 urban classes with a Minimum Mapping Unit (MMU) of 0.25 ha and for 10 rural classes with a MMU of 1 ha and is available as vector data.\r\n\r\nUse of ancillary data (Google Earth, OpenStreet Map).\r\n\r\nLC/LU misclassifications from 2018 are corrected but only in the immediate surroundings of the actual LC/LU change area. These corrections lead to the production of this revised LC/LU 2018 status layer.\r\n\r\nThe spatial expression of the 2018 revised dataset is compatible with the 2021 FUA boundaries of Urban Atlas.\r\n\r\nThe population density available in the 2018 original dataset is no longer available in the 2018 revised dataset due to the change of boundaries.</gco:CharacterString>\r\n      </mrl:statement>\r\n      <mrl:scope>\r\n        <mcc:MD_Scope>\r\n          <mcc:level>\r\n            <mcc:MD_ScopeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#MD_ScopeCode" codeListValue="dataset" />\r\n          </mcc:level>\r\n        </mcc:MD_Scope>\r\n      </mrl:scope>\r\n    </mrl:LI_Lineage>\r\n  </mdb:resourceLineage>\r\n  <mdb:metadataMaintenance>\r\n    <mmi:MD_MaintenanceInformation>\r\n      <mmi:maintenanceAndUpdateFrequency>\r\n        <mmi:MD_MaintenanceFrequencyCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#MD_MaintenanceFrequencyCode" codeListValue="" />\r\n      </mmi:maintenanceAndUpdateFrequency>\r\n    </mmi:MD_MaintenanceInformation>\r\n  </mdb:metadataMaintenance>\r\n</mdb:MD_Metadata>	2026-03-30T11:45:32.420712Z	2025-12-11T16:20:47.883223Z	0