nlineResource>\r\n      <cit:linkage>\r\n        <gco:CharacterString>https://sdi.eea.europa.eu/catalogue/srv/api/records/ee72f512-f4fa-4602-815e-3c6c99ed6d27</gco:CharacterString>\r\n      </cit:linkage>\r\n      <cit:function>\r\n        <cit:CI_OnLineFunctionCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_OnLineFunctionCode" codeListValue="completeMetadata" />\r\n      </cit:function>\r\n    </cit:CI_OnlineResource>\r\n  </mdb:metadataLinkage>\r\n  <mdb:identificationInfo>\r\n    <mri:MD_DataIdentification>\r\n      <mri:citation>\r\n        <cit:CI_Citation>\r\n          <cit:title>\r\n            <gco:CharacterString>Nationally designated areas for public access (tabular data) - version 21, Jun. 2023</gco:CharacterString>\r\n          </cit:title>\r\n          <cit:date>\r\n            <cit:CI_Date>\r\n              <cit:date>\r\n                <gco:Date>2023-05-26</gco:Date>\r\n              </cit:date>\r\n              <cit:dateType>\r\n                <cit:CI_DateTypeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_DateTypeCode" codeListValue="creation" />\r\n              </cit:dateType>\r\n            </cit:CI_Date>\r\n          </cit:date>\r\n          <cit:date>\r\n            <cit:CI_Date>\r\n              <cit:date>\r\n                <gco:Date>2023-08-04</gco:Date>\r\n              </cit:date>\r\n              <cit:dateType>\r\n                <cit:CI_DateTypeCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_DateTypeCode" codeListValue="publication" />\r\n              </cit:dateType>\r\n            </cit:CI_Date>\r\n          </cit:date>\r\n          <cit:identifier>\r\n            <mcc:MD_Identifier>\r\n              <mcc:code>\r\n                <gco:CharacterString>eea_t_designated-areas_p_2022-2023_v21_r00</gco:CharacterString>\r\n              </mcc:code>\r\n            </mcc:MD_Identifier>\r\n          </cit:identifier>\r\n        </cit:CI_Citation>\r\n      </mri:citation>\r\n      <mri:abstract>\r\n        <gco:CharacterString>The European inventory of Nationally designated areas holds information about protected designated areas and their designation types, which directly or indirectly create protected areas. The Nationally designated areas' dataset is the official source of protected area information from the 38 European countries*, members of the Eionet, to the World Database of Protected Areas (WDPA).\r\n\r\nThis metadata refers to the public version of the Nationally designated areas dataset version 21 (2023). The EEA does not have permission to distribute some or all sites reported by Estonia, Ireland and Türkiye. The internal version of this dataset "Nationally designated areas (CDDA) for internal use - version 21, Jun. 2023", from which this dataset is derived, contains all designated areas and its access is restricted.\r\n\r\nThe dataset contains tabular data: CDDA_2023_v01_public_DesignatedArea.csv, which includes information on the nationally designated sites and designated boundaries for public dissemination; and CDDA_2023_v01_public_DesignationType.csv, which contains information about designation types and the national and international legislative instruments, which directly or indirectly create protected designated areas in Europe.\r\n\r\nThis dataset is the accompaniment to two versions of publicly accessible spatial data: https://sdi.eea.europa.eu/catalogue/srv/eng/catalog.search#/metadata/ef77dd7b-e5d0-4b93-81e1-f721b91ec9fe\r\n\r\n* Including Kosovo (UNSCR 1244/99), which designation is without prejudice to positions on status, and is in line with UNSCR 1244 and the ICJ Opinion on the Kosovo Declaration of Independence.</gco:CharacterString>\r\n      </mri:abstract>\r\n      <mri:status>\r\n        <mcc:MD_ProgressCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#MD_ProgressCode" codeListValue="superseded" />\r\n      </mri:status>\r\n      <mri:pointOfContact>\r\n        <cit:CI_Responsibility>\r\n          <cit:role>\r\n            <cit:CI_RoleCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_RoleCode" codeListValue="pointOfContact" />\r\n          </cit:role>\r\n          <cit:party>\r\n            <cit:CI_Organisation>\r\n              <cit:name>\r\n                <gco:CharacterString>European Environment Agency</gco:CharacterString>\r\n              </cit:name>\r\n              <cit:contactInfo>\r\n                <cit:CI_Contact>\r\n                  <cit:address>\r\n                    <cit:CI_Address>\r\n                      <cit:deliveryPoint>\r\n                        <gco:CharacterString>Kongens Nytorv 6</gco:CharacterString>\r\n                      </cit:deliveryPoint>\r\n                      <cit:city>\r\n                        <gco:CharacterString>Copenhagen</gco:CharacterString>\r\n                      </cit:city>\r\n                      <cit:administrativeArea>\r\n                        <gco:CharacterString>K</gco:CharacterString>\r\n                      </cit:administrativeArea>\r\n                      <cit:postalCode>\r\n                        <gco:CharacterString>1050</gco:CharacterString>\r\n                      </cit:postalCode>\r\n                      <cit:country>\r\n                        <gco:CharacterString>Denmark</gco:CharacterString>\r\n                      </cit:country>\r\n                      <cit:electronicMailAddress>\r\n                        <gco:CharacterString>sdi@eea.europa.eu</gco:CharacterString>\r\n                      </cit:electronicMailAddress>\r\n                    </cit:CI_Address>\r\n                  </cit:address>\r\n                  <cit:onlineResource>\r\n                    <cit:CI_OnlineResource>\r\n                      <cit:linkage>\r\n                        <gco:CharacterString>http://www.eea.europa.eu</gco:CharacterString>\r\n                      </cit:linkage>\r\n                      <cit:protocol>\r\n                        <gco:CharacterString>WWW:LINK-1.0-http--link</gco:CharacterString>\r\n                      </cit:protocol>\r\n                      <cit:name>\r\n                        <gco:CharacterString>European Environment Agency public website</gco:CharacterString>\r\n                      </cit:name>\r\n                      <cit:function>\r\n                        <cit:CI_OnLineFunctionCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_OnLineFunctionCode" codeListValue="information" />\r\n                      </cit:function>\r\n                    </cit:CI_OnlineResource>\r\n                  </cit:onlineResource>\r\n                </cit:CI_Contact>\r\n              </cit:contactInfo>\r\n            </cit:CI_Organisation>\r\n          </cit:party>\r\n        </cit:CI_Responsibility>\r\n      </mri:pointOfContact>\r\n      <mri:pointOfContact>\r\n        <cit:CI_Responsibility>\r\n          <cit:role>\r\n            <cit:CI_RoleCode codeList="http://standards.iso.org/iso/19115/resources/Codelists/cat/codelists.xml#CI_RoleCode" codeListValue="custodian" />\r\n          </cit:role>\r\n          <cit:party>\r\n            <cit:CI_Organisation>\r\n              <cit:name>\r\n                <gco:CharacterString>European Environment Agency</gco:CharacterString>\r\n              </cit:name>\r\n              <cit:contactInfo>\r\n                <cit:CI_Contact>\r\n                  <cit:address>\r\n                    <cit:CI_Address>\r\n                      <cit:deliveryPoint>\r\n                        <gco:CharacterString>Kongens Nytorv 6</gco:CharacterString>\r\n                      </cit:deliveryPoint>\r\n                      <cit:city>\r\n                        <gco:CharacterString>Copenhagen</gco:CharacterString>\r\n                      </cit:city>\r\n                      <cit:administrativeArea>\r\n                        <gco:CharacterString>K</gco:CharacterS